package com.tarapickle.shared.api; import com.tarapickle.identity.application.IdentityException; import com.tarapickle.shared.application.ApplicationException; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(IdentityException.class) ResponseEntity<ApiError> identity(IdentityException e,HttpServletRequest r){return ResponseEntity.status(e.status()).body(error(e.status(),e.code(),e.getMessage(),r,List.of()));} @ExceptionHandler(ApplicationException.class) ResponseEntity<ApiError> application(ApplicationException e,HttpServletRequest r){return ResponseEntity.status(e.status()).body(error(e.status(),e.code(),e.getMessage(),r,List.of()));} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiError> validation(MethodArgumentNotValidException e,HttpServletRequest r){List<ApiErrorDetail> details=e.getBindingResult().getFieldErrors().stream().map(x->new ApiErrorDetail(x.getField(),"INVALID_FIELD",x.getDefaultMessage())).toList();return ResponseEntity.badRequest().body(error(HttpStatus.BAD_REQUEST,"VALIDATION_ERROR","One or more request fields are invalid.",r,details));} @ExceptionHandler(Exception.class) ResponseEntity<ApiError> unexpected(Exception e,HttpServletRequest r){return ResponseEntity.internalServerError().body(error(HttpStatus.INTERNAL_SERVER_ERROR,"INTERNAL_ERROR","An unexpected error occurred.",r,List.of()));} private ApiError error(HttpStatus s,String code,String detail,HttpServletRequest r,List<ApiErrorDetail> d){String trace=Optional.ofNullable(r.getHeader("X-Correlation-ID")).orElse(UUID.randomUUID().toString());return new ApiError("https://api.pickletayo.ph/problems/"+code.toLowerCase(Locale.ROOT).replace('_','-'),s.getReasonPhrase(),s.value(),code,detail,r.getRequestURI(),trace,d,Instant.now());}}
